    const name = String(rawFileName).trim().toLowerCase();
    const url = String(rawFileUrl).trim().toLowerCase();

    let mediaType = '';

    // 1. Explicit mediaType
    if (['audio', 'image', 'pdf'].includes(explicit)) {
      mediaType = explicit;
    }
    // 2. MIME type
    else if (mime === 'application/pdf' || mime.includes('pdf')) {
      mediaType = 'pdf';
    } else if (mime.startsWith('image/')) {
      mediaType = 'image';
    } else if (mime.startsWith('audio/')) {
      mediaType = 'audio';
    }
    // 3. Filename extension
    else if (name.endsWith('.pdf')) {
      mediaType = 'pdf';
    } else if (/\.(jpg|jpeg|png|webp|gif|bmp|svg)$/i.test(name)) {
      mediaType = 'image';
    } else if (/\.(mp3|wav|webm|m4a|ogg|aac|flac|oga)$/i.test(name)) {
      mediaType = 'audio';
    }
    // 4. Legacy containers
    else if (msg && msg.photo) {
      mediaType = 'image';
    } else if (msg && msg.document) {
      mediaType = 'pdf';
    } else if (msg && msg.voice) {
      mediaType = 'audio';
    }
    // 5. URL extension
    else if (/\.(pdf)(?:$|[?#])/i.test(url)) {
      mediaType = 'pdf';
    } else if (/\.(jpg|jpeg|png|webp|gif|bmp|svg)(?:$|[?#])/i.test(url)) {
      mediaType = 'image';
    } else if (/\.(mp3|wav|webm|m4a|ogg|aac|flac|oga)(?:$|[?#])/i.test(url)) {
      mediaType = 'audio';
    }

    let effectiveMime = rawMimeType;
    if (!effectiveMime) {
      if (mediaType === 'pdf') effectiveMime = 'application/pdf';
      else if (mediaType === 'image') effectiveMime = 'image/jpeg';
      else if (mediaType === 'audio') effectiveMime = 'audio/webm';
      else effectiveMime = 'application/octet-stream';
    }

    const effectiveFileName = rawFileName || (
      mediaType === 'pdf' ? 'document.pdf' :
      mediaType === 'image' ? 'image.jpg' :
      mediaType === 'audio' ? 'audio.webm' : 'file.bin'
    );

    // Diagnostics / Error check for missing URL or malformed query on direct upload
    if (rawFileUrl && typeof rawFileUrl === 'string' && rawFileUrl.startsWith('http')) {
      try {
        const parsedUrl = new URL(rawFileUrl);
        if (parsedUrl.search.includes('X-Amz-Signature') && !parsedUrl.search.includes('X-Amz-Credential')) {
          item.json.warning = 'Presigned storage URL appears to have malformed AWS/S3 query parameters.';
        }
      } catch (e) {
        item.json.warning = 'Invalid file URL syntax.';
      }
    }

    // Preserve all incoming metadata while assigning canonical properties
    item.json.mediaType = mediaType;
    item.json.mimeType = effectiveMime;
    item.json.mime_type = effectiveMime;
    item.json.fileName = effectiveFileName;
    item.json.file_name = effectiveFileName;
    item.json.fileUrl = rawFileUrl;
    item.json.file_url = rawFileUrl;
    item.json.fileSize = rawFileSize;
    item.json.file_size = rawFileSize;
    item.json.isDirectUpload = Boolean(rawFileUrl && String(rawFileUrl).startsWith('http'));

    // Legacy Base64 fallback handling if direct upload is false
    if (!item.json.isDirectUpload) {
      let legacyBase64 = '';
      if (msg && msg.photo && msg.photo[0]) {
        legacyBase64 = msg.photo[0].file_id || msg.photo[0].fileId || '';
      } else if (msg && msg.document) {
        legacyBase64 = msg.document.file_id || msg.document.fileId || '';
      } else if (msg && msg.voice) {
        legacyBase64 = msg.voice.file_id || msg.voice.fileId || '';
      }

      if (legacyBase64 && typeof legacyBase64 === 'string') {
        const base64Clean = legacyBase64.includes(',') ? legacyBase64.split(',')[1].trim() : legacyBase64.trim();
        item.binary = {
          data: {
            data: base64Clean,
            mimeType: effectiveMime,
            fileName: effectiveFileName
          }
        };
      }
    }
}

return items;

