    const base64Data = rawData.includes(',') ? rawData.split(',')[1].trim() : rawData.trim();
    item.binary = item.binary || {};
    item.binary.data = {
        data: base64Data,
        mimeType: 'application/pdf',
        fileName: 'upload_recovered.pdf'
    };
    if (item.json.error) {
        delete item.json.error;
        item.json.status = "Recovered via Base64 Fallback";
    }
} else {
    item.json.fallback_error = "Could not find a valid base64 document in the message payload.";
}

return item;

